import csv, os
VALID_CATEGORIES = {'grocery', 'travel', 'salary', 'rent', 'other'}
rejected = []
valid_count = 0
with open('data/events.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        amount_raw = row.get('amount','').strip()
        category = row.get('category','').strip()
        ok = True
        if not amount_raw:
            ok = False
        else:
            try:
                a = float(amount_raw)
                if a < 0 or a > 10000:
                    ok = False
            except: ok = False
        if category not in VALID_CATEGORIES:
            ok = False
        if ok: valid_count += 1
        else: rejected.append(row['row_id'])
print(f'Valid: {valid_count}, Rejected: {len(rejected)}')
for r in rejected: print(' REJECTED:', r)
"
